var minimumAddedInteger = function(nums1, nums2) {
    nums1.sort((a, b) => a - b);
    nums2.sort((a, b) => a - b);

    const candidates = [nums2[0] - nums1[0], nums2[0] - nums1[1], nums2[0] - nums1[2]];
    candidates.sort((a, b) => a - b);

    for (const diff of candidates) {
        let p1 = 0, p2 = 0;
        while (p1 < nums1.length && p2 < nums2.length) {
            if (nums1[p1] + diff === nums2[p2]) {
                p2++;
            }
            p1++;
        }
        if (p2 === nums2.length) {
            return diff;
        }
    }
    return candidates[0];
};
